313	// StreamLogs configures the logs emitted for upgraded streams.
314	type StreamLogs struct {
315		// If true, the access log entry of the request that upgraded to the
316		// stream (the handshake) is not written. The stream is still logged
317		// when it closes. Default: false, i.e. the handshake is logged.
318		SkipHandshake bool `json:"skip_handshake,omitempty"`
319	
320		// The level of the entry logged when a stream closes. The entry is
321		// written to the access loggers that apply to the request (see the
322		// server's logger_names), so it can be routed with a logger name like
323		// any access log entry. Default: DEBUG.
324		Level string `json:"level,omitempty"`
325	}
326	
327	// parseLevel returns the level of the stream close entry.
328	func (sl *StreamLogs) parseLevel() (zapcore.Level, error) {
329		if sl == nil || sl.Level == "" {
330			return zapcore.DebugLevel, nil
331		}
332		var level zapcore.Level
333		if err := level.UnmarshalText([]byte(sl.Level)); err != nil {
334			return zapcore.DebugLevel, fmt.Errorf("invalid level %q: %v", sl.Level, err)
335		}
336		return level, nil
337	}
338	
339	// skipHandshake returns whether the handshake must not be access logged.
340	func (sl *StreamLogs) skipHandshake() bool {
341		return sl != nil && sl.SkipHandshake
342	}
343	
344	// The results a stream can end with, as used in logs and metrics.
345	const (
346		// streamResultClosed is a stream that ended cleanly, from either side.
347		streamResultClosed = "closed"
348		// streamResultError is a stream that ended because of a copy error.
349		streamResultError = "error"
350		// streamResultTimeout is a stream that reached stream_timeout.
351		streamResultTimeout = "timeout"
352		// streamResultReload is a stream closed because its config was unloaded.
353		streamResultReload = "reload"
354		// streamResultUpstreamRemoved is a detached stream closed because its
355		// upstream is not part of the config anymore.
356		streamResultUpstreamRemoved = "upstream_removed"
357	)
358	
359	// upgradedStream tracks one upgraded stream: what it is connected to, how
360	// much data it moved and how it ended. It makes sure the stream is
361	// accounted exactly once, whichever of the paths that can end a stream
362	// (the copiers, a timeout, a reload, an upstream removal) gets there first.
363	type upgradedStream struct {
364		upstream string
365		start    time.Time
366	
367		toBackend   atomic.Int64
368		fromBackend atomic.Int64
369	
370		// closeConns closes both connections of a detached stream, nil otherwise
371		closeConns func()
372	
373		mu     sync.Mutex
374		forced string // result imposed by an outside close, first one wins
375		once   sync.Once
376	}
377	
378	// streamUpstream returns the upstream the request in ctx is proxied to,
379	// or an empty string if it isn't known.
380	func streamUpstream(ctx context.Context) string {
381		di, ok := GetDialInfo(ctx)
382		if !ok || di.Upstream == nil {
383			return ""
384		}
385		return di.Upstream.String()
386	}
387	
388	// newUpgradedStream starts accounting for a stream to upstream.
389	func newUpgradedStream(upstream string) *upgradedStream {
390		streamMetrics.opened(upstream)
391		return &upgradedStream{upstream: upstream, start: time.Now()}
392	}
393	
394	// markResult records why the stream is closed from the outside. Only the
395	// first call has an effect; it overrides the result the stream ends with,
396	// which would otherwise be an error caused by the closed connections.
397	func (s *upgradedStream) markResult(result string) {
398		s.mu.Lock()
399		defer s.mu.Unlock()
400		if s.forced == "" {
401			s.forced = result
402		}
403	}
404	
405	// streamSummary is what is known about a stream once it ended.
406	type streamSummary struct {
407		upstream    string
408		result      string
409		duration    time.Duration
410		toBackend   int64
411		fromBackend int64
412	}
413	
414	// finish ends the accounting of the stream with the given result, unless
415	// the stream was closed from the outside, in which case that result wins.
416	// Only the first call accounts the stream (and returns true); later calls
417	// are no-ops.
418	func (s *upgradedStream) finish(result string) (summary streamSummary, first bool) {
419		s.once.Do(func() {
420			first = true
421	
422			s.mu.Lock()
423			if s.forced != "" {
424				result = s.forced
425			}
426			s.mu.Unlock()
427	
428			summary = streamSummary{
429				upstream:    s.upstream,
430				result:      result,
431				duration:    time.Since(s.start),
432				toBackend:   s.toBackend.Load(),
433				fromBackend: s.fromBackend.Load(),
434			}
435			streamMetrics.closed(summary)
436		})
437		return summary, first
438	}
439	
440	// logStreamClosed writes the stream close entry to the access loggers
441	// of the request, at the configured level.
442	func (h *Handler) logStreamClosed(req *http.Request, summary streamSummary) {
443		server, ok := req.Context().Value(caddyhttp.ServerCtxKey).(*caddyhttp.Server)
444		if !ok {
445			return
446		}
447		for _, accessLogger := range server.AccessLoggers(req) {
448			if c := accessLogger.Check(h.streamLogLevel, "stream closed"); c != nil {
449				c.Write(
450					zap.String("upstream", summary.upstream),
451					zap.String("result", summary.result),
452					zap.Duration("duration", summary.duration),
453					zap.Int64("bytes_to_backend", summary.toBackend),
454					zap.Int64("bytes_from_backend", summary.fromBackend),
455				)
456			}
457		}
458	}
459	
460	// streamRegistry tracks the detached streams by upstream, so that the
461	// streams of an upstream can be closed when the upstream is removed from
462	// the config. It is global because detached streams outlive the handler
463	// (and the config) that created them.
464	type streamRegistry struct {
465		mu      sync.Mutex
466		streams map[string]map[*upgradedStream]struct{}
467	}
468	
469	var detachedStreams = &streamRegistry{streams: make(map[string]map[*upgradedStream]struct{})}
470	
471	// add tracks s until the returned function is called.
472	func (r *streamRegistry) add(s *upgradedStream) (remove func()) {
473		r.mu.Lock()
474		defer r.mu.Unlock()
475		if r.streams[s.upstream] == nil {
476			r.streams[s.upstream] = make(map[*upgradedStream]struct{})
477		}
478		r.streams[s.upstream][s] = struct{}{}
479		return func() {
480			r.mu.Lock()
481			defer r.mu.Unlock()
482			delete(r.streams[s.upstream], s)
483			if len(r.streams[s.upstream]) == 0 {
484				delete(r.streams, s.upstream)
485			}
486		}
487	}
488	
489	// closeUpstream closes all the streams to upstream, and returns how many
490	// there were. The streams are closed without holding the lock, since
491	// closing is potentially blocking and each stream removes itself when done.
492	func (r *streamRegistry) closeUpstream(upstream, result string) int {
493		r.mu.Lock()
494		closing := make([]*upgradedStream, 0, len(r.streams[upstream]))
495		for s := range r.streams[upstream] {
496			closing = append(closing, s)
497		}
498		r.mu.Unlock()
499	
500		for _, s := range closing {
501			s.markResult(result)
502			s.closeConns()
503		}
504		return len(closing)
505	}
506	
507	// flushInterval returns the p.FlushInterval value, conditionally
508	// overriding its value for a specific request/response.
509	func (h Handler) flushInterval(req *http.Request, res *http.Response, incremental bool) time.Duration {
510		// The upstream asked for the response to be forwarded incrementally.
511		// See RFC 10036: https://www.rfc-editor.org/rfc/rfc10036.html
512		if incremental || caddyhttp.IsIncremental(res.Header) {
513			return -1 // negative means immediately
514		}
515	
516		resCTHeader := res.Header.Get("Content-Type")
517		resCT, _, err := mime.ParseMediaType(resCTHeader)
518	
519		// For Server-Sent Events responses, flush immediately.
520		// The MIME type is defined in https://www.w3.org/TR/eventsource/#text-event-stream
521		if err == nil && resCT == "text/event-stream" {
522			return -1
523		}
524	
525		// We might have the case of streaming for which Content-Length might be unset.
526		if res.ContentLength == -1 {
527			return -1
528		}
